@import url('https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&display=swap');
:root{--gold:#d8b77a;--gold-bright:#f3d9a1;--ink:#090b11;--muted:#9a9aa0;--red:#bd4a50;--blue:#77b7d0;--panel:rgba(13,15,21,.78);--line:rgba(222,198,154,.22)}*{box-sizing:border-box}html,body,#game-root{width:100%;height:100%;margin:0;overflow:hidden;background:var(--ink);color:#f4f0e9;font-family:'DM Sans',sans-serif}body{user-select:none;-webkit-user-select:none;touch-action:none}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,7,12,.56),transparent 25%,transparent 60%,rgba(5,7,12,.64)),radial-gradient(ellipse at center,transparent 36%,rgba(4,5,9,.5) 100%)}.topbar{position:absolute;top:0;left:0;right:0;height:86px;padding:20px 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.07);background:linear-gradient(180deg,rgba(6,7,11,.74),transparent)}.brand{display:flex;align-items:center;gap:12px}.brand-mark{font-size:25px;color:var(--gold);text-shadow:0 0 20px #c79d54}.brand b{display:block;font:600 16px Cinzel,serif;letter-spacing:2px}.brand small{display:block;color:#a6a4a0;font:9px 'Space Mono',monospace;letter-spacing:2.2px;margin-top:3px}.dungeon-label{display:flex;align-items:center;gap:11px;position:absolute;left:50%;transform:translateX(-50%)}.live-dot{height:7px;width:7px;border-radius:50%;background:#c76662;box-shadow:0 0 12px #d45151}.dungeon-label small{display:block;color:#b1a995;font:9px 'Space Mono',monospace;letter-spacing:1.6px}.dungeon-label b{display:block;font:600 12px Cinzel,serif;letter-spacing:1.2px;margin-top:4px}.icon-button{width:39px;height:39px;border:1px solid rgba(230,216,191,.3);background:rgba(8,10,14,.4);color:#e4d7bf;font-size:18px;border-radius:50%;cursor:pointer}.player-hud{position:absolute;left:34px;top:110px;width:290px;display:flex;gap:13px;align-items:center}.portrait-wrap{position:relative;width:58px;height:58px;flex:none}.portrait{width:54px;height:54px;