ty .8s,visibility .8s}.screen-cover.dismissed{opacity:0;visibility:hidden;pointer-events:none}.intro-content{margin-top:8px;width:390px}.eyebrow{display:flex;align-items:center;gap:10px;color:#c7a975;font:9px 'Space Mono',monospace;letter-spacing:2px}.eyebrow i{width:18px;height:1px;background:#c7a975}.intro-content h1{font:500 clamp(62px,8vw,102px)/.91 Cinzel,serif;letter-spacing:5px;margin:22px 0 17px;text-shadow:0 3px 24px #000}.intro-content h1 em{font-style:normal;color:#cfb17a}.intro-content p{color:#c2c0bc;font:14px/1.8 'DM Sans',sans-serif;letter-spacing:.2px;margin:0 0 20px}.rank-intro{display:flex;align-items:center;gap:12px;margin:17px 0 23px}.rank-intro span,.rank-intro small{font:8px 'Space Mono',monospace;letter-spacing:1.3px;color:#a6a29c}.rank-intro b{width:31px;height:31px;border:1px solid #d1ad68;color:#e8c879;display:grid;place-items:center;font:700 18px Cinzel,serif;background:#a4874b24}.primary-button{height:47px;min-width:243px;padding:0 17px;border:1px solid #cfad70;background:linear-gradient(110deg,#b38e50,#725a35);color:#fff7e6;font:600 10px 'Space Mono',monospace;letter-spacing:1.2px;cursor:pointer;box-shadow:0 7px 30px #0008;transition:filter .2s,transform .2s}.primary-button:hover{filter:brightness(1.2);transform:translateY(-2px)}.primary-button span{font-size:15px;padding-left:22px}.intro-footer{margin-top:55px;color:#85817a;font:8px 'Space Mono',monospace;letter-spacing:1.7px}.intro-footer span{color:#bc9c64;padding:0 9px}.modal-layer{position:absolute;inset:0;display:grid;place-items:center;background:rgba(3,4,7,.65);backdrop-filter:blur(7px);padding:20px}.modal-card{position:relative;width:min(520px,94vw);max-height:85vh;overflow:auto;background:linear-gradient(145deg,rgba(23,25,30,.97),rgba(10,12,17,.97));border:1px solid rgba(204,174,117,.42);box-shadow:0 25px 100px #000b;padding:32px}.close-button{position:absolute;right:14px;top:10px;border:0;background:none;color:#d2c2a2;font-size:27px;cursor:pointer}.modal-title{font:500 24px Cinzel,serif;letter-spacing:2px;margin:0 0 5px}.modal-subtitle{font:9px 'Space Mono',monospace;color:#ad9c78;letter-spacing:1.3px;margin-bottom:24px}.stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.stat-row,.item-card{display:flex;align-items:center;justify-content:space-between;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.025);padding:12px}.stat-row span{color:#c2b9a7;font-size:11px}.stat-row b{font:13px 'Space Mono',monospace;color:#e4cfaa}.stat-row button{margin-left:8px;width:23px;height:23px;color:#d7b978;border:1px solid #7d6946;background:#171715;cursor:pointer}.points-note{margin-top:16px;color:#a9a39a;font:10px 'Space Mono',monospace}.item-list{display:grid;gap:9px}.item-card{gap:12px;justify-content:flex-start}.item-icon{width:38px;height:38px;display:grid;place-items:center;border:1px solid #a48a5c;color:#e0c58f;font-size:19px;flex:none;background:#d3a84f14}.item-copy{flex:1}.item-copy b{font:500 12px Cinzel,serif;display:block}.item-copy small{color:#a7a29a;font-size:10px;display:block;margin-top:4px}.rarity{color:#d7b978;font:8px 'Space Mono',monospace;letter-spacing:1px}.empty-inventory{color:#a8a39b;font-size:12px;line-height:1.7;padding:15px 0}.pause-actions{display:flex;gap:10px;margin-top:20px}.pause-actions button{flex:1;padding:13px 5px;border:1px solid var(--line);background:#ffffff08;color:#eee;font:9px 'Space Mono',monospace;letter-spacing:.7px;cursor:pointer}.level-flash{position:absolute;left:50%;top:42%;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;color:#e8d8ae;text-shadow:0 2px 14px #000;animation:flashIn .45s ease-out}.level-flash span{font-size:27px;color:#f2d594}.level-flash small{font:9px 'Space Mono',monospace;letter-spacing:2px;margin-top:8px}.level-flash b{font:500 38px Cinzel,serif;letter-spacing:3px}.level-flash em{font:16px 'Space Mono',monospace;color:#d4b474;font-style:normal}@keyframes flashIn{from{opacity:0;transform:translate(-50%,-40%) scale(.8)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}
