import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const canvas = document.querySelector('#scene');
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x090c13);
scene.fog = new THREE.FogExp2(0x0b1017, 0.023);
const camera = new THREE.PerspectiveCamera(54, innerWidth/innerHeight, .1, 150);
const clock = new THREE.Clock();
const ambient = new THREE.HemisphereLight(0x8996a9, 0x171219, 1.35); scene.add(ambient);
const moon = new THREE.DirectionalLight(0xa6c8e5, 2.4); moon.position.set(-14,22,10); moon.castShadow=true; moon.shadow.mapSize.set(1024,1024); moon.shadow.camera.left=-35; moon.shadow.camera.right=35; moon.shadow.camera.top=35; moon.shadow.camera.bottom=-50; scene.add(moon);
const torchLight = new THREE.PointLight(0xd36b37, 5, 22, 2); torchLight.position.set(1,4,-7); scene.add(torchLight);
const gateLight = new THREE.PointLight(0x5f7cbd, 7, 34, 1.7); gateLight.position.set(0,5,-45); scene.add(gateLight);
const world = new THREE.Group(); scene.add(world);
const mat = (color, roughness=.8, metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const stone=mat(0x252a31), stoneLight=mat(0x3c4148), darkStone=mat(0x171a21), gold=mat(0xb79761,.45,.65), iron=mat(0x59616a,.35,.72), cloth=mat(0x20232b), skin=mat(0xc0a98d), glowBlue=new THREE.MeshBasicMaterial({color:0x83c1e3}), flameMat=new THREE.MeshBasicMaterial({color:0xf18a46});
const boxGeo=new THREE.BoxGeometry(1,1,1), sphereGeo=new THREE.SphereGeometry(1,12,10), cylinderGeo=new THREE.CylinderGeometry(.5,.5,1,10);
function mesh(geo, material, parent=world){const m=new THREE.Mesh(geo,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function block(x,y,z,sx,sy,sz,material=stone){const m=mesh(boxGeo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);return m;}
function makeTexture(){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.fillStyle='#24282e';x.fillRect(0,0,256,256);for(let i=0;i<2400;i++){const v=30+Math.random()*40;x.fillStyle=`rgba(${v},${v+2},${v+6},${Math.random()*.2})`;x.fillRect(Math.random()*256,Math.random()*256,Math.random()*3+1,Math.random()*3+1)}x.strokeStyle='rgba(120,126,133,.18)';x.lineWidth=2;for(let i=0;i<8;i++){x.beginPath();x.moveTo(Math.random()*256,Math.random()*256);x.lineTo(Math.random()*256,Math.random()*256);x.stroke()}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(3,10);t.colorSpace=THREE.SRGBColorSpace;return t;}
const floorMat=new THREE.MeshStandardMaterial({map:makeTexture(),color:0xaaa9a4,roughness:.96});
const floor=mesh(new THREE.PlaneGeometry(34,116),floorMat);floor.rotation.x=-Math.PI/2;floor.position.set(0,-.08,-38);floor.receiveShadow=true;
// broken flagstones and borders
for(let z=12;z>-91;z-=4){for(let x=-14;x<=14;x+=4){if(Math.abs(x)<6 && Math.random()>.34)continue;const tile=block(x,-.01,z+(Math.random()-.5)*.8,3.8,.12,3.7,Math.random()>.6?stoneLight:stone);tile.rotation.y=(Math.random()-.5)*.04;}}
for(const side of [-1,1]){
  block(side*16,.25,-38,1.3,.5,116,darkStone);
  for(let z=10;z>-89;z-=12){block(side*8,3,z,1.05,6,1.05,stoneLight);block(side*8,6,z,.6,.35,.6,gold);}
  for(let z=8;z>-90;z-=16){const p=block(side*15,2,z,.24,4,.24,gold);const flame=mesh(new THREE.IcosahedronGeometry(.2,1),flameMat);flame.position.set(side*15,4.7,z);const l=new THREE.PointLight(0xe68247,2.4,11,2);l.position.set(side*15,4.8,z);world.add(l);}
}
// arches, sealed gate and environmental rubble
for(let z=-2;z>-84;z-=20){for(const side of [-1,1]){block(side*6,3,z,.7,6,.8,stoneLight);block(side*6,6,z,1.2,.45,1.25,gold);}block(0,6,z,12,.5,1,stone);}
for(let i=0;i<20;i++){const x=(Math.random()-.5)*25,z=-Math.random()*92;const b=block(x,.15,z,.5+Math.random()*1.3,.25+Math.random()*.5,.5+Math.random()*1.3,stoneLight);b.rotation.y=Math.random()*2;}
const gateGroup=new THREE.Group();world.add(gateGroup);
for(let side of [-1,1]){const p=mesh(new THREE.CylinderGeometry(1.05,1.35,9,12),stoneLight,gateGroup);p.position.set(side*6,4.5,-90);const cap=mesh(new THREE.CylinderGeometry(1.4,1.4,.7,12),gold,gateGroup);cap.position.set(side*6,9,-90);}
const arch=mesh(new THREE.TorusGeometry(6,1.1,8,24,Math.PI),gold,gateGroup);arch.position.set(0,8,-90);arch.rotation.z=Math.PI;
const portal=mesh(new THREE.PlaneGeometry(10,9),new THREE.MeshBasicMaterial({color:0x233d68,transparent:true,opacity:.63,side:THREE.DoubleSide}),gateGroup);portal.position.set(0,4.5,-89.4);
for(let i=0;i<5;i++){const shard=mesh(new THREE.OctahedronGeometry(.18+Math.random()*.25),glowBlue);shard.position.set((Math.random()-.5)*8,1+Math.random()*7,-88.8);}
// Hunter model built from readable, low-poly armor pieces
