function makeEnemy(type,x,z,boss=false){const g=new THREE.Group();let height=boss?3.7:type==='brute'?2.8:type==='stalker'?1.9:2.25;const skinMat=boss?mat(0x30374b,.4,.25):type==='stalker'?mat(0x464d57):type==='brute'?mat(0x4b382f):mat(0x343b46);const torso=mesh(new THREE.CapsuleGeometry(boss?.65:.42,height*.28,4,8),skinMat,g);torso.position.y=height*.48;const head=mesh(new THREE.SphereGeometry(boss?.5:.34,12,10),skinMat,g);head.position.y=height*.86;const eyeMat=new THREE.MeshBasicMaterial({color:boss?0x8bc5f2:0xde5b62});for(const side of [-1,1]){const eye=mesh(new THREE.SphereGeometry(boss?.095:.065,8,8),eyeMat,g);eye.position.set(side*(boss?.23:.15),height*.88,-(boss?.4:.28));}const shoulderMat=boss?gold:stoneLight;for(const side of [-1,1]){const arm=mesh(new THREE.CapsuleGeometry(boss?.22:.14,boss?.75:.5,3,6),shoulderMat,g);arm.position.set(side*(boss?.75:.5),height*.53,0);arm.rotation.z=side*-.22;const leg=mesh(new THREE.CapsuleGeometry(.16,boss?.8:.58,3,6),darkStone,g);leg.position.set(side*.24,height*.16,0);}if(type==='stalker'&&!boss){const horns=new THREE.ConeGeometry(.13,.5,5);for(let s of [-1,1]){const h=mesh(horns,gold,g);h.position.set(s*.22,height*.92,0);h.rotation.z=s*.3;}}if(type==='brute'&&!boss){const club=mesh(new THREE.CylinderGeometry(.11,.2,.9,6),gold,g);club.position.set(.67,height*.4,-.08);club.rotation.z=-.4;}if(boss){const crown=mesh(new THREE.ConeGeometry(.67,.75,6),gold,g);crown.position.y=height+0.12;for(let i=0;i<3;i++){const spike=mesh(new THREE.ConeGeometry(.2,.8,5),iron,g);spike.position.set((i-1)*.52,height*.77,-.08);spike.rotation.z=(i-1)*-.3;}}
g.position.set(x,0,z);g.userData={type,boss,hp:boss?420:type==='brute'?95:type==='stalker'?55:65,maxHp:boss?420:type==='brute'?95:type==='stalker'?55:65,damage:boss?22:type==='brute'?15:type==='stalker'?10:9,speed:boss?1.5:type==='stalker'?2.5:type==='brute'?1.15:1.75,attackTimer:Math.random(),phase:Math.random()*6,body:torso};world.add(g);enemies.push(g);return g;}
