let boss=null, bossAwake=false, bossKilled=false;
const state={hp:100,maxHp:100,xp:0,nextXp:100,level:1,rank:'F',kills:0,points:0,strength:5,agility:5,vitality:5,intelligence:5,critical:10,inventory:[],attackCooldown:0,skillCooldown:0,gameStarted:false,paused:false,dead:false};
function spawnBoss(){if(bossAwake)return;bossAwake=true;boss=makeEnemy('warden',0,-73,true);document.querySelector('#boss-bar').classList.remove('hidden');toast('THE DROWNED WARDEN HAS AWAKENED');document.querySelector('#quest-text').textContent='Defeat the Drowned Warden';document.querySelector('#quest-progress').textContent='The gatekeeper stands between you and the exit';}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),2700);}
function setRank(){const ranks=['F','E','D','C','B','A','S','SS','SSS'];const index=Math.min(8,Math.floor((state.level-1)/2));state.rank=ranks[index];document.querySelector('#rank').textContent=state.rank;}
function updateHud(){const hpPct=Math.max(0,state.hp/state.maxHp*100);document.querySelector('#hp-fill').style.width=hpPct+'%';document.querySelector('#hp-text').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;document.querySelector('#xp-fill').style.width=(state.xp/state.nextXp*100)+'%';document.querySelector('#xp-text').textContent=`${state.xp} / ${state.nextXp} XP`;document.querySelector('#level-label').textContent=`LVL ${String(state.level).padStart(2,'0')}`;document.querySelector('#kill-count').textContent=bossKilled?'COMPLETE':`${state.kills} / 6`;document.querySelector('#loot-badge').textContent=state.inventory.length;}
function addXp(amount){state.xp+=amount;while(state.xp>=state.nextXp){state.xp-=state.nextXp;state.level++;state.points+=3;state.nextXp=Math.round(state.nextXp*1.35);state.maxHp+=12;state.hp=Math.min(state.maxHp,state.hp+35);setRank();document.querySelector('#level-flash-number').textContent=String(state.level).padStart(2,'0');const flash=document.querySelector('#level-flash');flash.classList.remove('hidden');setTimeout(()=>flash.classList.add('hidden'),1900);toast('A new strength awakens within you');}updateHud();}
function burst(position,color=0x9edcf3,count=12){const particles=[];for(let i=0;i<count;i++){const p=mesh(new THREE.SphereGeometry(.045+Math.random()*.04,6,6),new THREE.MeshBasicMaterial({color,transparent:true}),world);p.position.copy(position);p.userData.velocity=new THREE.Vector3((Math.random()-.5)*4,Math.random()*3,(Math.random()-.5)*4);particles.push(p);}effects.push({particles,life:.65,max:.65});}
function dropLoot(enemy){const choices=[{name:'Rustbound Greatsword',icon:'⚔',desc:'+4 Strength · A weathered blade with an unbroken will',rarity:'UNCOMMON'},{name:'Warden's Sigil',icon:'◈',desc:'+3 Vitality · A fragment of the gatekeeper',rarity:'RARE'},{name:'Ashen Shard',icon:'✧',desc:'+25 XP · Resonant dungeon crystal',rarity:'COMMON'},{name:'Nightweave Mantle',icon:'♢',desc:'+2 Agility · Woven from shadow silk',rarity:'UNCOMMON'}];const item=choices[Math.floor(Math.random()*choices.length)];const orb=mesh(new THREE.OctahedronGeometry(.22,0),new THREE.MeshStandardMaterial({color:item.rarity==='RARE'?0x71b9e2:0xd9b56c,emissive:item.rarity==='RARE'?0x285878:0x574021,emissiveIntensity:1.3}),world);orb.position.copy(enemy.position);orb.position.y=.6;drops.push({mesh:orb,item});toast(`${item.rarity} LOOT: ${item.name}`);}
function killEnemy(enemy){const isBoss=enemy.userData.boss;burst(enemy.position.clone().add(new THREE.Vector3(0,1,0)),isBoss?0x86c8f2:0xd27679,isBoss?35:18);world.remove(enemy);const idx=enemies.indexOf(enemy);if(idx>=0)enemies.splice(idx,1);if(isBoss){bossKilled=true;document.querySelector('#boss-bar').classList.add('hidden');document.querySelector('#quest-text').textContent='Sanctum Purged';document.querySelector('#quest-progress').textContent='The hunter has survived the impossible';toast('GATE CLEARED — YOU ARE NO LONGER THE WEAKEST');dropLoot(enemy);addXp(250);return;}state.kills++;addXp(enemy.userData.type==='brute'?42:enemy.userData.type==='stalker'?32:30);if(Math.random()<.78)dropLoot(enemy);updateHud();if(state.kills>=6)spawnBoss();}

