const input={x:0,y:0,keys:new Set(),attack:false};let cameraYaw=0,attackAnim=0,attackSerial=0;
function doAttack(special=false){if(!state.gameStarted||state.paused||state.dead)return;if(special){if(state.skillCooldown>0)return;state.skillCooldown=8;const radius=6.2;let hit=0;for(const e of [...enemies])if(player.position.distanceTo(e.position)<radius){damageEnemy(e,40+state.intelligence*3,true);hit++;}burst(player.position.clone().add(new THREE.Vector3(0,1,0)),0x70c7ed,22);toast(hit?`VEIL BURST · ${hit} TARGET${hit===1?'':'S'} STRUCK`:'VEIL BURST');return;}if(state.attackCooldown>0)return;state.attackCooldown=.48;attackAnim=.38;attackSerial++;const dir=new THREE.Vector3(-Math.sin(player.rotation.y),0,-Math.cos(player.rotation.y));let target=null,best=3.15;for(const e of enemies){const delta=e.position.clone().sub(player.position);const distance=delta.length();const facing=dir.dot(delta.normalize());if(distance<best&&facing>-.3){best=distance;target=e;}}if(target){const critical=Math.random()<Math.min(.5,state.critical/100);const damage=(13+state.strength*2)*(critical?1.8:1);damageEnemy(target,damage,critical);burst(target.position.clone().add(new THREE.Vector3(0,1.3,0)),critical?0xffd57e:0x9ec9da,critical?12:7);}else{burst(player.position.clone().add(dir.multiplyScalar(1.6)).add(new THREE.Vector3(0,1.2,0)),0x9da6b6,4);}}
function damageEnemy(enemy,amount,critical=false){if(!enemy.parent)return;enemy.userData.hp-=amount;enemy.userData.hitFlash=.14;enemy.scale.setScalar(enemy.userData.boss?1.04:1.12);if(enemy.userData.boss)document.querySelector('#boss-fill').style.width=Math.max(0,enemy.userData.hp/enemy.userData.maxHp*100)+'%';if(critical)toast(`CRITICAL · ${Math.round(amount)} DAMAGE`);if(enemy.userData.hp<=0)killEnemy(enemy);}
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();input.keys.add(key);if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(key===' '&&!e.repeat)doAttack();if(key==='q'&&!e.repeat)doAttack(true);if(key==='i'&&!e.repeat)openModal('inventory');if(key==='c'&&!e.repeat)openModal('status');if(key==='escape')togglePause();});window.addEventListener('keyup',e=>input.keys.delete(e.key.toLowerCase()));
const stickZone=document.querySelector('#stick-zone'),stickKnob=document.querySelector('#stick-knob');let stickPointer=null;
stickZone.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stickZone.setPointerCapture(e.pointerId);moveStick(e);});stickZone.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e);});function moveStick(e){const r=stickZone.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=43,len=Math.hypot(dx,dy),scale=Math.min(1,max/(len||1));input.x=dx*scale/max;input.y=dy*scale/max;stickKnob.style.left=`calc(50% + ${dx*scale}px)`;stickKnob.style.top=`calc(50% + ${dy*scale}px)`;}function releaseStick(){stickPointer=null;input.x=0;input.y=0;stickKnob.style.left='50%';stickKnob.style.top='50%';}stickZone.addEventListener('pointerup',releaseStick);stickZone.addEventListener('pointercancel',releaseStick);
document.querySelector('#attack-button').addEventListener('pointerdown',e=>{e.preventDefault();doAttack();});document.querySelector('#special-button').addEventListener('pointerdown',e=>{e.preventDefault();doAttack(true);});
let drag=null;canvas.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.pointerType==='touch')return;drag={x:e.clientX,y:e.clientY};});window.addEventListener('pointermove',e=>{if(!drag)return;cameraYaw-= (e.clientX-drag.x)*.004;drag={x:e.clientX,y:e.clientY};});window.addEventListener('pointerup',()=>drag=null);
function openModal(type){state.paused=true;const modal=document.querySelector('#modal-layer'),content=document.querySelector('#modal-content');modal.classList.remove('hidden');if(type==='status'){content.innerHTML=`<h2 class="modal-title">HUNTER STATUS</h2><div class="modal-subtitle">AWAKENED · RANK ${state.rank} · LEVEL ${state.level}</div><div class="stat-grid">${[['Strength','strength'],['Agility','agility'],['Vitality','vitality'],['Intelligence','intelligence'],['Critical damage','critical']].map(([label,key])=>`<div class="stat-row"><span>${label}</span><div><b>${key==='critical'?state[key]+'%':state[key]}</b>${state.points?`<button data-stat="${key}">+</button>`:''}</div></div>`).join('')}</div><div class="points-note">UNALLOCATED ATTRIBUTE POINTS <b style="color:#e2c47f">${state.points}</b><br>Spend points to grow stronger.</div><div class="pause-actions"><button id="resume-button">RETURN TO DUNGEON</button><button id="status-inventory">VIEW RELICS</button></div>`;content.querySelectorAll('[data-stat]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.stat;if(!state.points)return;state.points--;state[key]+=key==='critical'?2:1;if(key==='vitality'){state.maxHp+=8;state.hp+=8}openModal('status');updateHud();});content.querySelector('#resume-button').onclick=closeModal;content.querySelector('#status-inventory').onclick=()=>openModal('inventory');}else if(type==='inventory'){content.innerHTML=`<h2 class="modal-title">RELICS & LOOT</h2><div class="modal-subtitle">CARRIED ITEMS · ${state.inventory.length} / 12</div>${state.inventory.length?`<div class="item-list">${state.inventory.map(item=>`<div class="item-card"><div class="item-icon">${item.icon}</div><div class="item-copy"><b>${item.name}</b><small>${item.desc}</small></div><div class="rarity">${item.rarity}</div></div>`).join('')}</div>`:`<div class="empty-inventory">Your pack is empty. Defeat the guardians and search their remains for relics.<br><br><span style="color:#cfad70">TIP</span> Move close to a fallen enemy's glowing drop to collect it.</div>`}<div class="pause-actions"><button id="resume-button">RETURN TO DUNGEON</button><button id="status-inventory">CHARACTER STATUS</button></div>`;content.querySelector('#resume-button').onclick=closeModal;content.querySelector('#status-inventory').onclick=()=>openModal('status');}else{content.innerHTML=`<h2 class="modal-title">THE HUNT IS PAUSED</h2><div class="modal-subtitle">YOUR FATE IS STILL UNWRITTEN</div><div class="pause-actions"><button id="resume-button">RESUME HUNT</button><button id="status-inventory">HUNTER STATUS</button></div>`;content.querySelector('#resume-button').onclick=closeModal;content.querySelector('#status-inventory').onclick=()=>openModal('status');}}
function closeModal(){document.querySelector('#modal-layer').classList.add('hidden');state.paused=false;}function togglePause(){if(!state.gameStarted)return;if(state.paused)closeModal();else openModal('pause');}
document.querySelector('#close-modal').addEventListener('click',closeModal);document.querySelector('#modal-layer').addEventListener('click',e=>{if(e.target.id==='modal-layer')closeModal();});document.querySelector('#status-button').addEventListener('click',()=>openModal('status'));document.querySelector('#inventory-button').addEventListener('click',()=>openModal('inventory'));document.querySelector('#menu-button').addEventListener('click',togglePause);
document.querySelector('#begin-button').addEventListener('click',()=>{state.gameStarted=true;document.querySelector('#intro-screen').classList.add('dismissed');toast('HUNT BEGINS · MOVE TOWARD THE SANCTUM');});

